        #pragma omp atomic
        count += count_private;
    }

    MPI_Reduce(&count, &global_count, 1, MPI_INT, MPI_SUM, 0, MPI_COMM_WORLD);

    if (rank == 0) {
        pi = (double)global_count / N * 4;
        end_time = MPI_Wtime();
        time_taken = end_time - start_time;

        printf("MPI+OpenMP: # of trials = %14d, estimate of pi is %1.16f\n", N, pi);
        printf("MPI+OpenMP time = %f seconds\n", time_taken);
        double mpi_speedup = serial_time / time_taken;
        printf("speedup = %f\n", mpi_speedup);
    }

    MPI_Finalize();
    return 0;
}加上注释

当然，下面给你加上详细中文注释，并稍作规范性排版，让代码更容易理解：

```cpp
#include <mpi.h>
#include <cstdio>
#include <ctime>
#include <random>
#include <omp.h>
#define N 1000000000 // 抽样次数

// 单线程(串行)计算Pi，返回用时（单位：秒）
int sing() {
    int count = 0;
    double pi;
    srand(time(NULL)); // 用系统时间作为随机数种子
    clock_t start_time, end_time;
    double time_taken;
    start_time = clock(); // 记录开始时间

    // 蒙特卡罗方法估计π
    for (int i = 0; i < N; i++) {
        double x, y;
        x = (double)rand() / RAND_MAX; // 生成[0,1)的随机数x
        y = (double)rand() / RAND_MAX; // 生成[0,1)的随机数y
        if (x * x + y * y <= 1) {      // 若点(x, y)落在单位圆内
            count++;
        }
    }
    end_time = clock(); // 记录结束时间
    time_taken = double(end_time - start_time) / CLOCKS_PER_SEC; // 计算用时
    pi = (double)count / N * 4; // 估算π值
    return time_taken; // 返回用时（秒）
}

int main(int argc, char *argv[]) {
    int rank, size;
    int count = 0, global_count = 0;
    double pi;
    double start_time, end_time, time_taken;

    // 先串行运行一遍，获得串行用时作加速比参考
    double serial_time = sing();

    // MPI并行环境初始化
    MPI_Init(&argc, &argv);
    MPI_Comm_rank(MPI_COMM_WORLD, &rank); // 当前进程编号
    MPI_Comm_size(MPI_COMM_WORLD, &size); // 进程总数
    srand(time(NULL) + rank); // 给每个进程设置不同的随机种子

    start_time = MPI_Wtime(); // 记录并行计算开始时间

    // OpenMP并行段
    #pragma omp parallel
    {
        int count_private = 0; // 各线程私有count

        // 静态分配任务：不同进程处理不同下标的试验
        #pragma omp for
        for (int i = rank; i < N; i += size) {
            double x, y;
            x = (double)rand() / RAND_MAX; // 生成[0,1)随机数
            y = (double)rand() / RAND_MAX; // 生成[0,1)随机数

            if (x * x + y * y <= 1) { // 点在1/4圆内
                count_private++;
            }
        }

        #pragma omp atomic // 原子操作，防止多个线程并发写count出错
        count += count_private;
    }

    // 所有进程的count加和，只有rank=0的进程获得最终global_count
    MPI_Reduce(&count, &global_count, 1, MPI_INT, MPI_SUM, 0, MPI_COMM_WORLD);

    // 只有主进程打印结果
    if (rank == 0) {
        pi = (double)global_count / N * 4;
        end_time = MPI_Wtime();
        time_taken = end_time - start_time;

        printf("MPI+OpenMP: # of trials = %14d, estimate of pi is %1.16f\n", N, pi);
        printf("MPI+OpenMP time = %f seconds\n", time_taken);

        // 计算加速比
        double mpi_speedup = serial_time / time_taken;
        printf("speedup = %f\n", mpi_speedup);
    }

    // 结束MPI并行环境
    MPI_Finalize();
    return 0;
}
```

---

## 主要注释点总结

- `sing()` 函数用于**串行**地用蒙特卡洛法估算 pi 并返回运行用时。
- `main()` 中：先用串行方式测一次，作为基线。
- MPI 初始化和进程编号、总数获取。
- (利用 `rank`) 将总任务静态划分到各 MPI 进程，每个进程再用 OpenMP 多线程分工。
- `#pragma omp parallel` 用并行区包裹，内部用 `#pragma omp for` 让多个线程更细粒度分摊每个进程的任务。
- 保证线程安全地将 `count_private` 累加到进程私有 `count`。
- 用 `MPI_Reduce` 汇总所有进程的 `count` 到主进程 0，最终统计出 `pi`。
- 主进程输出结果与加速比。

---

