class Car:
    def __init__(self, make, model, year):
        self.make = make
        self.model = model
        self.year = year
        self.mileage = 0
        self.mileage_history = [self.mileage]

    def display_info(self):
        print(f"Car Information:")
        print(f"Make: {self.make}")
        print(f"Model: {self.model}")
        print(f"Year: {self.year}")
        print(f"Current Mileage: {self.mileage} miles")

    def increase_mileage(self, miles):
        if miles < 0:
            return
        self.mileage += miles
        self.mileage_history.append(self.mileage)

    def reset_mileage(self, new_mileage):
        if new_mileage not in self.mileage_history or new_mileage > self.mileage:
            print("Error: Invalid reset value")
            return
        self.mileage = new_mileage

if __name__ == "__main__":
    try:
        make = input()
        model = input()
        year = input()
        car = Car(make, model, year)
        while True:
            inp = input()
            if inp.startswith("DISPLAY"):
                car.display_info()
            elif inp.startswith("INCREASE"):
                try:
                    _, n = inp.split()
                    n = int(n)
                    car.increase_mileage(n)
                except:
                    pass
            elif inp.startswith("RESET"):
                try:
                    _, n = inp.split()
                    n = int(n)
                    car.reset_mileage(n)
                except:
                    print("Error: Invalid reset value")
    except EOFError:
        pass

